  print("Finding solutions for number = $n and prime = $p:");
  if (p == 2 || !isPrime(p)) {
    print("No solutions, since p is not an odd prime.\n");
    return;
  }
  // p is an odd prime
  if (legendreSymbol(n, p) != 1) {
    print("No solutions, since $n is not a square in F$p\n");
    return;
  }
  int a, w2;
  int x1, x2;
  Fp2 result = Fp2(0, 0);
  while (true) {
    do {
      a = rangeRandom(2, p);
      w2 = a * a - n;
    } while (legendreSymbol(w2, p) != -1);
    result.x = a;
    result.y = 1;
    result = powerFp2(result, (p + 1) ~/ 2, p, w2);
    if (result.y != 0) {
      continue;
    }
    x1 = result.x;
    x2 = p - x1;
    if (multiplyModulus(x1, x1, p) == n && multiplyModulus(x2, x2, p) == n) {
      print("Square roots of $n are ($x1 and $x2) mod $p\n");
      return;
    }
  }
}

digits(n) sync* {
  double a = 0, b = 1;
  for (var i = 0; i < n; i++) {
    yield b.toString().codeUnitAt(0) - 48;
    (a, b) = (b, a + b);
  }
}

@pragma('vm:entry-point')
lineout(s1, s2, s3) {
  print(
    s1.toString().padLeft(8) +
        s2.toString().padLeft(12) +
        s3.toString().padLeft(12),
  );
}

@pragma('vm:entry-point')
main() {
  @pragma('vm:entry-point')
  var tally = List<int>.filled(9, 0);
  for (var d in digits(1000)) {
    tally[d - 1] += 1;
  }

  lineout("Digit", "Expected", "Actual");
  print("-" * 40);

  for (var d = 1; d < 10; d += 1) {
    lineout(
      d,
      (log(1 + 1 / d) * log10e).toStringAsFixed(4),
      (tally[d - 1] / 1000).toStringAsFixed(3),
    );
  }
}
